CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "Holidays" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Date" date NOT NULL,
        "Name" character varying(100) NOT NULL,
        "City" character varying(100),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Holidays" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "OutboxMessages" (
        "Id" uuid NOT NULL,
        "EventType" character varying(200) NOT NULL,
        "PayloadJson" text NOT NULL,
        "OccurredAtUtc" timestamp with time zone NOT NULL,
        "ProcessedAtUtc" timestamp with time zone,
        "AttemptCount" integer NOT NULL,
        "LastError" character varying(2000),
        CONSTRAINT "PK_OutboxMessages" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "Payments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(30) NOT NULL,
        "BookingId" integer,
        "BookingCode" character varying(30),
        "ParkingSessionId" integer,
        "UserId" integer,
        "ParkingLotId" integer NOT NULL,
        "OwnerProfileId" integer NOT NULL,
        "Purpose" character varying(40) NOT NULL,
        "Method" character varying(40) NOT NULL,
        "Status" character varying(40) NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "RefundedAmount" numeric(18,2) NOT NULL,
        "Currency" character varying(3) NOT NULL,
        "IdempotencyKey" character varying(100) NOT NULL,
        "ProviderTransactionId" character varying(100),
        "ProviderResponseCode" character varying(20),
        "RawCallbackJson" text,
        "TransferContent" character varying(100),
        "PaidAtUtc" timestamp with time zone,
        "ExpiresAtUtc" timestamp with time zone,
        "ConfirmedByStaffId" integer,
        "RetryCount" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Payments_Amount" CHECK ([Amount] >= 0 AND [RefundedAmount] >= 0 AND [RefundedAmount] <= [Amount]),
        CONSTRAINT "CK_Payments_Target" CHECK ([BookingId] IS NOT NULL OR [ParkingSessionId] IS NOT NULL)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "Promotions" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(30) NOT NULL,
        "Name" character varying(150) NOT NULL,
        "ParkingLotId" integer,
        "OwnerProfileId" integer,
        "Sponsor" character varying(40) NOT NULL,
        "DiscountType" character varying(40) NOT NULL,
        "DiscountValue" numeric(18,2) NOT NULL,
        "MaxDiscountAmount" numeric(18,2),
        "MinOrderAmount" numeric(18,2),
        "StartsAtUtc" timestamp with time zone NOT NULL,
        "EndsAtUtc" timestamp with time zone NOT NULL,
        "UsageLimit" integer,
        "UsedCount" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Promotions" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Promotions_Period" CHECK ([EndsAtUtc] > [StartsAtUtc])
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "RateCards" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ParkingLotId" integer NOT NULL,
        "OwnerProfileId" integer NOT NULL,
        "Name" character varying(100) NOT NULL,
        "EffectiveFromUtc" timestamp with time zone NOT NULL,
        "EffectiveToUtc" timestamp with time zone,
        "IsActive" boolean NOT NULL,
        "OvernightSurcharge" numeric(18,2) NOT NULL,
        "WeekendMultiplier" numeric(4,2) NOT NULL,
        "HolidayMultiplier" numeric(4,2) NOT NULL,
        "OversizedMultiplier" numeric(4,2) NOT NULL,
        "OverstayMultiplier" numeric(4,2) NOT NULL,
        "MaxDailyAmount" numeric(18,2),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_RateCards" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_RateCards_Multipliers" CHECK ([WeekendMultiplier] > 0 AND [HolidayMultiplier] > 0 AND [OversizedMultiplier] >= 1 AND [OverstayMultiplier] >= 1)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "Settlements" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OwnerProfileId" integer NOT NULL,
        "PeriodStart" date NOT NULL,
        "PeriodEnd" date NOT NULL,
        "GrossAmount" numeric(18,2) NOT NULL,
        "CommissionRate" numeric(5,4) NOT NULL,
        "CommissionAmount" numeric(18,2) NOT NULL,
        "RefundAmount" numeric(18,2) NOT NULL,
        "HeldAmount" numeric(18,2) NOT NULL,
        "AdjustmentAmount" numeric(18,2) NOT NULL,
        "NetPayout" numeric(18,2) NOT NULL,
        "Status" character varying(40) NOT NULL,
        "ApprovedByUserId" integer,
        "ApprovedAtUtc" timestamp with time zone,
        "PaidAtUtc" timestamp with time zone,
        "PayoutReference" character varying(100),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Settlements" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Settlements_Period" CHECK ([PeriodEnd] >= [PeriodStart])
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "CompensationVouchers" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" character varying(30) NOT NULL,
        "UserId" integer NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "Reason" character varying(500) NOT NULL,
        "BookingId" integer,
        "ComplaintId" integer,
        "ChargedToOwnerProfileId" integer,
        "ExpiresAtUtc" timestamp with time zone NOT NULL,
        "Status" character varying(40) NOT NULL,
        "RedeemedAtUtc" timestamp with time zone,
        "RedeemedPaymentId" integer,
        "IssuedByUserId" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_CompensationVouchers" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_CompensationVouchers_Amount" CHECK ([Amount] > 0),
        CONSTRAINT "FK_CompensationVouchers_Payments_RedeemedPaymentId" FOREIGN KEY ("RedeemedPaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
