        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PaymentId" integer,
        "Provider" character varying(40) NOT NULL,
        "ProviderTransactionId" character varying(100),
        "RawPayload" text NOT NULL,
        "SignatureValid" boolean NOT NULL,
        "IsDuplicate" boolean NOT NULL,
        "ResultCode" character varying(20),
        "ProcessingError" character varying(1000),
        "SourceIp" character varying(45),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_PaymentCallbackLogs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_PaymentCallbackLogs_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
