    CREATE TABLE "Refunds" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PaymentId" integer NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "Reason" character varying(40) NOT NULL,
        "Note" character varying(1000),
        "Status" character varying(40) NOT NULL,
        "ComplaintId" integer,
        "RequestedByUserId" integer,
        "ApprovedByUserId" integer,
        "ProviderRefundId" character varying(100),
        "ProcessedAtUtc" timestamp with time zone,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Refunds" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Refunds_Amount" CHECK ([Amount] > 0),
        CONSTRAINT "FK_Refunds_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "PromotionRedemptions" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PromotionId" integer NOT NULL,
        "UserId" integer NOT NULL,
