        "PaymentId" integer,
        "DiscountAmount" numeric(18,2) NOT NULL,
        "IsReverted" boolean NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_PromotionRedemptions" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_PromotionRedemptions_Amount" CHECK ([DiscountAmount] >= 0),
        CONSTRAINT "FK_PromotionRedemptions_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_PromotionRedemptions_Promotions_PromotionId" FOREIGN KEY ("PromotionId") REFERENCES "Promotions" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "RateRules" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RateCardId" integer NOT NULL,
        "VehicleType" character varying(40) NOT NULL,
        "FromMinute" integer NOT NULL,
        "ToMinute" integer,
        "BlockMinutes" integer NOT NULL,
        "PricePerBlock" numeric(18,2) NOT NULL,
        "SortOrder" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_RateRules" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_RateRules_Block" CHECK ([BlockMinutes] > 0 AND [PricePerBlock] >= 0),
        CONSTRAINT "CK_RateRules_Range" CHECK ([ToMinute] IS NULL OR [ToMinute] > [FromMinute]),
        CONSTRAINT "FK_RateRules_RateCards_RateCardId" FOREIGN KEY ("RateCardId") REFERENCES "RateCards" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "FinancialAdjustments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OwnerProfileId" integer NOT NULL,
        "SettlementId" integer,
        "Amount" numeric(18,2) NOT NULL,
        "Reason" character varying(500) NOT NULL,
        "CreatedByUserId" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_FinancialAdjustments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_FinancialAdjustments_Settlements_SettlementId" FOREIGN KEY ("SettlementId") REFERENCES "Settlements" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003092328_InitialCreate') THEN
    CREATE TABLE "Invoices" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Type" character varying(40) NOT NULL,
        "PaymentId" integer,
        "SettlementId" integer,
        "InvoiceNumber" character varying(30) NOT NULL,
        "BuyerName" character varying(200) NOT NULL,
        "BuyerTaxCode" character varying(20),
        "BuyerEmail" character varying(256),
        "SubTotal" numeric(18,2) NOT NULL,
        "VatAmount" numeric(18,2) NOT NULL,
        "Total" numeric(18,2) NOT NULL,
        "IssuedAtUtc" timestamp with time zone NOT NULL,
        "PdfUrl" character varying(512),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Invoices" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Invoices_Source" CHECK (([Type] = N'ParkingFee' AND [PaymentId] IS NOT NULL) OR ([Type] = N'PlatformCommission' AND [SettlementId] IS NOT NULL)),
        CONSTRAINT "FK_Invoices_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Invoices_Settlements_SettlementId" FOREIGN KEY ("SettlementId") REFERENCES "Settlements" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
