        CONSTRAINT "FK_SettlementLines_Payments_PaymentId" FOREIGN KEY ("PaymentId") REFERENCES "Payments" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_SettlementLines_Refunds_RefundId" FOREIGN KEY ("RefundId") REFERENCES "Refunds" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_SettlementLines_Settlements_SettlementId" FOREIGN KEY ("SettlementId") REFERENCES "Settlements" ("Id") ON DELETE RESTRICT
